            --e-global-color-heaven2: var(--global-palette2);
            --e-global-color-heaven3: var(--global-palette3);
            --e-global-color-heaven4: var(--global-palette4);
            --e-global-color-heaven5: var(--global-palette5);
            --e-global-color-heaven6: var(--global-palette6);
